--
-- Table structure for table `offer_letters`
--

DROP TABLE IF EXISTS `offer_letters`;
SET @saved_cs_client     = @@character_set_client;
SET character_set_client = utf8mb4;
CREATE TABLE `offer_letters` (
  `id` int NOT NULL AUTO_INCREMENT,
  `applicationId` int NOT NULL,
  `companyId` int NOT NULL,
  `candidateId` int NOT NULL,
  `jobId` int NOT NULL,
  `template` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'modern',
  `offerContent` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `salary` decimal(12,2) NOT NULL,
  `joiningDate` date NOT NULL,
  `workLocation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `benefits` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` enum('draft','sent','viewed','accepted','rejected','expired') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `sentAt` timestamp NULL DEFAULT NULL,
  `viewedAt` timestamp NULL DEFAULT NULL,
  `expiresAt` timestamp NULL DEFAULT NULL,
  `acceptedAt` timestamp NULL DEFAULT NULL,
  `rejectedAt` timestamp NULL DEFAULT NULL,
  `createdBy` int NOT NULL,
  `updatedBy` int DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `pdfUrl` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trackingToken` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expiresIn` int DEFAULT '7',
  `createdAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trackingToken` (`trackingToken`),
  KEY `candidateId` (`candidateId`),
  KEY `jobId` (`jobId`),
  KEY `createdBy` (`createdBy`),
  KEY `idx_application` (`applicationId`),
  KEY `idx_company_created` (`companyId`,`createdAt`),
  KEY `idx_status` (`status`),
  KEY `idx_expires` (`expiresAt`),
  KEY `offer_letters_application_id` (`applicationId`),
  KEY `offer_letters_company_id_created_at` (`companyId`,`createdAt`),
  KEY `offer_letters_status` (`status`),
